# CMake 使用要求（usage requirements）传播求解器
PROPAGATE = ("PUBLIC", "INTERFACE")   # 会向消费者传播的关键字


def interface_includes(g, t):
    """t 导出给消费者的 include 目录（INTERFACE_INCLUDE_DIRECTORIES）。"""
    out = set()
    for dep, kw in g[t]["deps"]:
        if kw in PROPAGATE:
            out |= set(g[dep]["inc"])
            out |= interface_includes(g, dep)
    return out


def usage_includes(g, t):
    """t 自己编译时实际可见的 include 目录 = 自己的 + 从依赖继承的。"""
    return set(g[t]["inc"]) | interface_includes(g, t)


def interface_links(g, t):
    return sorted(d for d, kw in g[t]["deps"] if kw in PROPAGATE)


def show(title, g):
    print("[%s]" % title)
    for t in sorted(g):
        print("  %-5s 自用 include=%s" % (t, sorted(g[t]["inc"])))
        print("  %-5s 对外 INTERFACE_INCLUDE_DIRECTORIES=%s" % (t, sorted(interface_includes(g, t))))
        print("  %-5s 对外 INTERFACE_LINK_LIBRARIES=%s" % (t, interface_links(g, t)))
        print("  %-5s 编译期可见 include=%s" % (t, sorted(usage_includes(g, t))))
    ok = "core/include" in usage_includes(g, "app")
    print("  判定 app 可直接使用 core 的头文件 = %s" % ok)
    return ok


GOOD = {
    "core": {"inc": ["core/include"], "deps": []},
    "math": {"inc": ["math/include"], "deps": [("core", "PUBLIC")]},
    "app":  {"inc": ["app/src"],      "deps": [("math", "PRIVATE")]},
}
BAD = {
    "core": {"inc": ["core/include"], "deps": []},
    "math": {"inc": ["math/include"], "deps": [("core", "PRIVATE")]},
    "app":  {"inc": ["app/src"],      "deps": [("math", "PRIVATE")]},
}

a = show("图 A：math 以 PUBLIC 链接 core（传播成立）", GOOD)
b = show("图 B：math 以 PRIVATE 链接 core（不传播）", BAD)

print("[结论] 图 B 中 app 若直接 include core 的头文件会编译失败：")
print("       PRIVATE 依赖只对 math 自己可见，不会被 app 继承（这正是漏写 PUBLIC 的典型后果）")
print("[判定] 4 个传播判定全部符合预期 = %s" % (a and (not b)))
